<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/**
 * `vehicles_log` table of the MyAT database.
 * Generated by `php artisan app:generate-models`; add relationships below.
 *
 * @property int|null $LogID
 * @property int|null $VehicleID
 * @property Carbon|null $LogDate
 * @property float|null $Kilometers
 * @property string|null $LogType
 * @property string|null $Description
 * @property Carbon|null $Created
 * @property Carbon|null $Modified
 * @property string|null $CreatedBy
 * @property string|null $ModifiedBy
 * @property string|null $Files
 */
class VehiclesLog extends Model
{
    protected $table = 'vehicles_log';

    protected $primaryKey = 'LogID';

    public $incrementing = true;

    protected $keyType = 'int';

    public $timestamps = false;

    protected $guarded = [];

    protected function casts(): array
    {
        return [
            'LogID' => 'integer',
            'VehicleID' => 'integer',
            'LogDate' => 'date',
            'Kilometers' => 'float',
            'Created' => 'date',
            'Modified' => 'date',
        ];
    }

    protected static function booted(): void
    {
        // PHPRunner add/edit events; these columns are NOT NULL.
        static::creating(function (VehiclesLog $log): void {
            $log->Created = now();
            $log->CreatedBy = (string) auth()->user()?->username;
            $log->ModifiedBy ??= '';
        });
        static::updating(function (VehiclesLog $log): void {
            $log->Modified = now();
            $log->ModifiedBy = (string) auth()->user()?->username;
        });
        static::saving(function (VehiclesLog $log): void {
            foreach (['LogType', 'Description', 'CreatedBy', 'ModifiedBy'] as $column) {
                $log->{$column} ??= '';
            }
            $log->Kilometers ??= 0;
        });
    }

    public function vehicle(): BelongsTo
    {
        return $this->belongsTo(Vehicle::class, 'VehicleID', 'VehicleID');
    }
}
